let qrGenToken=0;async function generateQr(){const e=document.getElementById("qrInput").value,t=document.getElementById("qrCanvas"),n=document.getElementById("qrEmpty"),o=document.getElementById("qrActions"),r=document.getElementById("qrError");if(r.textContent="",!e.trim())return t.style.display="none",n.style.display="",void(o.style.display="none");const l=++qrGenToken,d=document.getElementById("qrLevel").value,a=parseInt(document.getElementById("qrScale").value,10)||6,c=document.getElementById("qrDark").value||"#000000",m=document.getElementById("qrLight").value||"#ffffff";try{if(await window.QRCode.toCanvas(t,e,{errorCorrectionLevel:d,scale:a,margin:2,color:{dark:c,light:m}}),l!==qrGenToken)return;t.style.display="",n.style.display="none",o.style.display=""}catch(e){if(l!==qrGenToken)return;t.style.display="none",n.style.display="none",o.style.display="none",r.textContent="Could not generate a QR code: "+e.message+". Try a shorter input or a lower error-correction level."}}function downloadPng(){const e=document.getElementById("qrCanvas"),t=document.createElement("a");t.href=e.toDataURL("image/png"),t.download="qrcode.png",document.body.appendChild(t),t.click(),t.remove()}async function downloadSvg(){const e=document.getElementById("qrInput").value;if(!e.trim())return;const t=document.getElementById("qrLevel").value,n=document.getElementById("qrDark").value||"#000000",o=document.getElementById("qrLight").value||"#ffffff",r=await window.QRCode.toString(e,{type:"svg",errorCorrectionLevel:t,margin:2,color:{dark:n,light:o}}),l=new Blob([r],{type:"image/svg+xml"}),d=URL.createObjectURL(l),a=document.createElement("a");a.href=d,a.download="qrcode.svg",document.body.appendChild(a),a.click(),a.remove(),URL.revokeObjectURL(d)}function clearQrInput(){document.getElementById("qrInput").value="",generateQr()}function tryQrExample(){document.getElementById("qrInput").value="https://toolsharp.dev",generateQr()}document.addEventListener("DOMContentLoaded",()=>{document.getElementById("qrScaleVal").textContent=document.getElementById("qrScale").value});